let allData = [];
let stockData = [];
let selectedTicker = null;

// Set up dimensions and margins
const chartMargin = { top: 20, right: 20, bottom: 20, left: 20 };
const chartWidth = 800 - chartMargin.left - chartMargin.right;
const chartHeight = 600 - chartMargin.top - chartMargin.bottom;

// Color scale for sectors
const colorScale = {
    'Information Technology': '#4CAF50',
    'Industry': '#FF9800',
    'Energy': '#F44336',
    'Financial': '#2196F3',
    'ETF': '#9C27B0'
};

// Format market cap numbers
function formatMarketCap(value) {
    if (value === null || value === undefined || isNaN(value)) {
        return 'N/A';
    }

    const trillions = value / 1000000000000;
    const billions = value / 1000000000;
    const millions = value / 1000000;

    if (trillions >= 1) {
        return trillions.toFixed(2) + 'T';
    } else if (billions >= 1) {
        return billions.toFixed(2) + 'B';
    } else if (millions >= 1) {
        return millions.toFixed(2) + 'M';
    } else {
        return value.toFixed(2);
    }
}

// Load and parse CSV data
async function loadData() {
    try {
        const data = await d3.csv('data/stock-descriptions.csv');
        allData = data.filter(d => d.ticker).map(d => ({
            ticker: d.ticker,
            sector: d.sector,
            fullName: d['full name'],
            marketCap: d.marketCap ? +d.marketCap : null,
            country: d.country,
            website: d.website
        }));

        console.log('Loaded data:', allData.length, 'stocks');
        return allData;
    } catch (error) {
        console.error('Error loading data:', error);
        return [];
    }
}

// Create bubble chart
function createBubbleChart(data) {
    // Clear previous chart
    d3.select('#bubble-chart').selectAll('*').remove();

    const svg = d3.select('#bubble-chart')
        .append('svg')
        .attr('width', chartWidth + chartMargin.left + chartMargin.right)
        .attr('height', chartHeight + chartMargin.top + chartMargin.bottom)
        .append('g')
        .attr('transform', `translate(${chartMargin.left},${chartMargin.top})`);

    // Get unique sectors and create force centers
    const sectors = [...new Set(data.map(d => d.sector))];
    const sectorCenters = {};
    const centerSpacing = Math.min(chartWidth, chartHeight) / (sectors.length + 1);

    sectors.forEach((sector, i) => {
        const x = (i + 1) * (chartWidth / (sectors.length + 1));
        const y = chartHeight / 2;
        sectorCenters[sector] = { x, y };
    });

    // Scale for bubble radius
    const stocksWithMarketCap = data.filter(d => d.marketCap !== null);
    const radiusScale = d3.scaleSqrt()
        .domain(d3.extent(stocksWithMarketCap, d => d.marketCap))
        .range([15, 60]);

    const etfRadius = 25;

    // Create simulation
    const simulation = d3.forceSimulation(data)
        .force('charge', d3.forceManyBody().strength(5))
        .force('collide', d3.forceCollide().radius(d => d.marketCap ? radiusScale(d.marketCap) + 3 : etfRadius + 3).iterations(2))
        .force('x', d3.forceX(d => sectorCenters[d.sector].x).strength(0.1))
        .force('y', d3.forceY(d => sectorCenters[d.sector].y).strength(0.1))
        .alphaDecay(0.03);

    // Create bubbles
    const bubbles = svg.selectAll('.bubble-group')
        .data(data)
        .enter()
        .append('g')
        .attr('class', 'bubble-group')
        .style('cursor', 'pointer');

    bubbles.append('circle')
        .attr('class', 'bubble')
        .attr('r', d => d.marketCap ? radiusScale(d.marketCap) : etfRadius)
        .attr('fill', d => colorScale[d.sector])
        .attr('opacity', 0.8);

    bubbles.append('text')
        .attr('class', 'bubble-text')
        .attr('text-anchor', 'middle')
        .attr('dy', '0.3em')
        .text(d => d.ticker);

    // Add tooltip functionality
    const tooltip = d3.select('#tooltip');

    bubbles.on('mouseover', function(event, d) {
        if (d.marketCap && d.fullName && d.sector) {
            tooltip
                .style('display', 'block')
                .style('left', (event.pageX + 10) + 'px')
                .style('top', (event.pageY - 10) + 'px')
                .html(`
                    <strong>Ticker:</strong> ${d.ticker}<br>
                    <strong>Name:</strong> ${d.fullName}<br>
                    <strong>Sector:</strong> ${d.sector}
                `);
        }
    })
    .on('mousemove', function(event) {
        tooltip
            .style('left', (event.pageX + 10) + 'px')
            .style('top', (event.pageY - 10) + 'px');
    })
    .on('mouseout', function() {
        tooltip.style('display', 'none');
    })
    .on('click', function(event, d) {
        selectStock(d.ticker);
        event.stopPropagation();
    });

    // Update positions on simulation tick
    simulation.on('tick', () => {
        bubbles.attr('transform', d => {
            d.x = Math.max(30, Math.min(chartWidth - 30, d.x));
            d.y = Math.max(30, Math.min(chartHeight - 30, d.y));
            return `translate(${d.x},${d.y})`;
        });
    });

    // Add click handler to clear selection
    svg.on('click', function() {
        clearSelection();
    });

    // Create legend
    createLegend(sectors);

    return simulation;
}

// Create legend
function createLegend(sectors) {
    d3.select('#legend').selectAll('*').remove();

    const legendSvg = d3.select('#legend')
        .attr('width', chartWidth)
        .attr('height', 50);

    const legendItems = legendSvg.selectAll('.legend-item')
        .data(sectors)
        .enter()
        .append('g')
        .attr('class', 'legend-item')
        .attr('transform', (d, i) => `translate(${i * (chartWidth / sectors.length)}, 10)`);

    legendItems.append('rect')
        .attr('class', 'legend-rect')
        .attr('width', 18)
        .attr('height', 18)
        .attr('fill', d => colorScale[d]);

    legendItems.append('text')
        .attr('class', 'legend-text')
        .attr('x', 24)
        .attr('y', 14)
        .text(d => d)
        .style('font-size', '11px');
}

// Create data table
function createTable(data) {
    const tbody = d3.select('#table-body');
    tbody.selectAll('tr').remove();

    const rows = tbody.selectAll('tr')
        .data(data)
        .enter()
        .append('tr')
        .attr('data-ticker', d => d.ticker)
        .style('cursor', 'pointer')
        .on('click', function(event, d) {
            selectBubble(d.ticker);
        });

    rows.selectAll('td')
        .data(d => [
            d.ticker,
            d.fullName || 'N/A',
            d.sector,
            formatMarketCap(d.marketCap)
        ])
        .enter()
        .append('td')
        .text(d => d);
}

// Format market cap column
function formatMarketCapColumn() {
    d3.select('#table-body').selectAll('tr').each(function(d) {
        const marketCapCell = d3.select(this).selectAll('td').filter((td, i) => i === 3);
        marketCapCell.text(formatMarketCap(d.marketCap));
    });
}

// Select stock (from bubble or table)
function selectStock(ticker) {
    selectedTicker = ticker;

    // Highlight bubble
    d3.selectAll('.bubble').classed('highlighted', false);
    d3.selectAll('.bubble-group').each(function(d) {
        if (d.ticker === ticker) {
            d3.select(this).select('.bubble').classed('highlighted', true);
        }
    });

    // Highlight table row
    d3.select('#table-body').selectAll('tr').classed('selected', false);
    d3.select(`#table-body tr[data-ticker="${ticker}"]`).classed('selected', true);

    // Scroll to highlighted row
    const selectedRow = d3.select(`#table-body tr[data-ticker="${ticker}"]`).node();
    if (selectedRow) {
        selectedRow.scrollIntoView({ block: 'nearest', behavior: 'smooth' });
    }
}

// Select bubble (from table)
function selectBubble(ticker) {
    selectStock(ticker);
}

// Clear selection
function clearSelection() {
    selectedTicker = null;
    d3.selectAll('.bubble').classed('highlighted', false);
    d3.select('#table-body').selectAll('tr').classed('selected', false);
}

// Initialize visualization
async function init() {
    stockData = await loadData();

    if (stockData.length === 0) {
        console.error('No data loaded');
        return;
    }

    // Sort data by market cap (descending)
    stockData.sort((a, b) => {
        if (a.marketCap === null && b.marketCap === null) return 0;
        if (a.marketCap === null) return 1;
        if (b.marketCap === null) return -1;
        return b.marketCap - a.marketCap;
    });

    // Create visualizations
    const simulation = createBubbleChart(stockData);
    createTable(stockData);

    console.log('Visualization initialized');
}

// Initialize when DOM is loaded
document.addEventListener('DOMContentLoaded', init);

